# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots stale_generation refusal record", type: :request do
  it "answers 409 stale_generation to a previous-generation delivery from the relay and records a refusal row for its company" do
    company = create(:company)
    # The suite starts at generation 1, and the contract refuses a generation
    # below 1 as invalid_snapshot, so raise it before building a stale batch.
    TimekeepingOwnership.current.update!(generation: 2)
    project = create(:project, client: create(:client, company:), billable: false)
    entry = TimekeepingSnapshots.entry(id: 92_301, company_id: company.id, version: 1, project_id: project.id,
                                       user_id: create(:user).id)
    body = TimekeepingSnapshots.batch(
      TimekeepingSnapshots.item(entry, generation: TimekeepingOwnership.current.generation - 1, outbox_position: 1)
    ).to_json

    with_timekeeping_service_token do |service_token|
      post "/internal/v1/timekeeping/entry-snapshots", params: body,
                                                       headers: { "CONTENT_TYPE" => "application/json",
                                                                  "Idempotency-Key" => SecureRandom.uuid,
                                                                  "Authorization" => "Bearer #{service_token}" }
    end

    # "any `409 stale_generation` outside a handoff;"
    expect(response.status).to eq(409)
    expect(response.parsed_body).to eq("reason" => "stale_generation")
    expect(TimekeepingStaleGenerationRefusal.where(company_id: company.id).pluck(:handoff_step)).to eq([nil])
  end
end
